positive_words = {"bueno", "rapido", "excelente", "encanto"}
negative_words = {"malo", "lento", "terrible", "danado"}


def strip_accents(word):
    table = str.maketrans("áéíóúñ", "aeioun")
    return word.translate(table)


def analyze(text):
    words = [strip_accents(w.strip(".,!¡")) for w in text.lower().split()]
    pos = sum(1 for w in words if w in positive_words)
    neg = sum(1 for w in words if w in negative_words)
    total = pos + neg
    if total == 0:
        return "neutral", 0.5
    if pos > neg:
        label = "positive"
    elif neg > pos:
        label = "negative"
    else:
        label = "mixed"
    confidence = max(pos, neg) / total
    return label, confidence


tickets = [
    "El servicio fue terrible y el envio lento",
    "Producto excelente, todo bueno",
    "Terrible experiencia, muy malo todo",
    "Recibi el pedido, sin comentarios",
]

threshold = 0.8
for ticket in tickets:
    label, confidence = analyze(ticket)
    if label == "negative" and confidence >= threshold:
        route = "senior agent"
    elif confidence < threshold:
        route = "manual review queue"
    else:
        route = "auto-close"
    print(f"{label} ({confidence:.2f}) -> {route}")
